-- ============================================================================
-- 2. ULTRA FAST DELTA CACHE VIDEO PLAYER ENGINE
-- ============================================================================
local function DrawUniversalCinema()
    local START_X = 2
    local START_Y = 2 
    
    local SCREEN_W = _G["cinema_screen_x"]
    local SCREEN_H = _G["cinema_screen_y"]
    
    -- Tablica przechowująca stan poprzedniej klatki w pamięci podręcznej
    if not _G["cinema_last_frame_buffer"] then
        _G["cinema_last_frame_buffer"] = {}
    end
    local lastFrame = _G["cinema_last_frame_buffer"]
    
    if not _G["cinema_cached_frames"] and _G["cinema_video_frames"] then
        _G["cinema_cached_frames"] = {}
        local b64_lut = {}
        local b64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        for i = 1, #b64_chars do b64_lut[string.sub(b64_chars, i, i)] = i - 1 end

        for fIdx = 1, #_G["cinema_video_frames"] do
            local b64Data = _G["cinema_video_frames"][fIdx]
            local frameRuns = {}
            
            for charIdx = 1, #b64Data do
                local char = string.sub(b64Data, charIdx, charIdx)
                local val = b64_lut[char]
                
                if val then
                    local pixelType = math.floor(val / 32)
                    local length = (val % 32) + 1
                    local targetCellID = color_id_map[pixelType] or 4501
                    table.insert(frameRuns, targetCellID)
                    table.insert(frameRuns, length)
                end
            end
            _G["cinema_cached_frames"][fIdx] = frameRuns
        end
    end

    local cachedLines = _G["cinema_cached_frames"]
    local currentFrame = _G["cinema_video_current_frame"] or 1

    if cachedLines and cachedLines[currentFrame] then
        local rleData = cachedLines[currentFrame]
        local pixelIdx = 0

        for i = 1, #rleData, 2 do
            local targetCellID = rleData[i]
            local length = rleData[i+1]

            for run = 1, length do
                -- Sprawdzamy, czy ten piksel zmienił się w stosunku do poprzedniej klatki
                if lastFrame[pixelIdx] ~= targetCellID then
                    local col = (pixelIdx % SCREEN_W) + 1
                    local row = math.floor(pixelIdx / SCREEN_W)
                    local spawnX = START_X + col
                    local spawnY = START_Y + row

                    -- Rysujemy blok na mapie TYLKO jeśli nastąpiła zmiana koloru piksela
                    SetCell(spawnX, spawnY, {id=targetCellID, rot=0, lastvars={spawnX,spawnY,0}, vars={}})
                    
                    -- Zapisujemy nowy stan piksela w buforze pamięci
                    lastFrame[pixelIdx] = targetCellID
                end
                pixelIdx = pixelIdx + 1
            end
        end
        
        _G["cinema_video_current_frame"] = currentFrame + 1
        if _G["cinema_video_current_frame"] > #cachedLines then 
            _G["cinema_video_current_frame"] = 1 
        end
    end
end

